export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;

/**
 * The MHPCO price list prices each main item type by its own tariff row, but
 * prices every component by one rule: 25 G per component, whatever its kind.
 */
const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BASE_PREMIUM = 25;

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.has(type);
}

function basePremiumFor(type: string): number {
  return isComponent(type) ? COMPONENT_BASE_PREMIUM : MAIN_ITEM_BASE_PREMIUM[type];
}
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

// Percentages are kept as exact fractions (integer numerator over PERCENT);
// scaling by a float rate such as 0.1 yields artefacts like 115.00000000000001.
function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

/** MHPCO rounds a premium up: every fraction of a G falls to the customer. */
function roundInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

function policyBasePremium(items: Item[]): number {
  return items.reduce((total, item) => total + basePremiumFor(item.type), 0);
}

export function quote(customer: Customer, items: Item[], previousContracts: number): number {
  const policyBase = policyBasePremium(items);
  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundInMHPCOsFavor(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
}

